<?php session_start(); require_once __DIR__.'/../config/config.php'; if(is_admin()){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=db()->prepare('SELECT * FROM admins WHERE username=? LIMIT 1');$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_user']=$a['username'];header('Location:index.php');exit;} $err='بيانات الدخول غير صحيحة';}catch(Throwable $e){$err='تعذر الاتصال بقاعدة البيانات. تأكد من الإعدادات.';}} ?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thaer Media Admin</title><link rel="stylesheet" href="admin.css"></head><body><div class="login"><h1>Thaer Media</h1><p>لوحة التحكم</p><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><label>اسم المستخدم<input name="username" value="admin" required></label><label>كلمة المرور<input type="password" name="password" value="password" required></label><button>دخول</button></form><small>الافتراضي: admin / password</small></div></body></html>
